<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useBookingStore } from '@/stores/booking'; import { api, errorMessage } from '@/lib/api'
import DatePicker from '@/components/DatePicker.vue'
const route=useRoute(); const router=useRouter(); const store=useBookingStore(); const date=ref(new Date(Date.now()+86400000).toISOString().slice(0,10)); const court=computed(()=>store.courts.find(item=>item.id===Number(route.params.id))||store.courts[0]); const money=(v:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(v); const error=ref(''); const loading=ref(false); onMounted(async()=>{try{await store.loadCourts(); if(court.value)await store.loadAvailability(court.value.id,date.value)}catch{error.value=store.error}}); async function refresh(){if(court.value)try{await store.loadAvailability(court.value.id,date.value)}catch{error.value=store.error}}; async function next(){if(!store.selectedSlots.length)return; loading.value=true; error.value=''; try { const payload = { court_id: court.value?.id, slots: store.selectedSlots.map((slot) => slot.startsAt) }; const result = route.query.reschedule ? await api.post<{booking:{code:string}}>('/bookings/' + route.query.reschedule + '/reschedule', payload) : await store.createBooking(); router.push('/payment/' + result.booking.code) } catch (cause:unknown) { error.value=errorMessage(cause,'Không thể tạo lịch đặt sân.') } finally { loading.value=false }}
</script>
<template><section class="page-shell"><div class="eyebrow">Đặt sân</div><h1 class="page-title">Chọn khung giờ.</h1><p class="muted">{{court?.name||'Aura Court'}} · Chọn một hoặc nhiều khung giờ liên tiếp.</p><div class="panel" style="margin-top:30px"><div class="row"><div><strong>Chọn ngày</strong><p class="muted" style="margin:5px 0 0">Khung giờ 60 phút · Giá hiển thị theo lịch</p></div><DatePicker v-model="date" @change="refresh" /></div><div class="slot-grid"><button v-for="slot in store.slots" :key="slot.startsAt" class="slot" :class="{selected:store.selectedSlots.some(item=>item.startsAt===slot.startsAt),unavailable:!slot.available}" :disabled="!slot.available" @click="store.toggle(slot)">{{new Date(slot.startsAt).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}}<br><small>{{money(slot.price)}}</small></button></div><p v-if="error" class="error">{{error}}</p><div class="row" style="margin-top:28px"><span class="muted">{{store.selectedSlots.length}} khung giờ đã chọn</span><button class="btn" :disabled="!store.selectedSlots.length||loading" @click="next">{{loading?'Đang giữ chỗ…':'Xem lại và thanh toán'}} <span class="material-symbols-outlined">arrow_forward</span></button></div></div></section></template>
